 }
 /* the header of the revised slab schedule (owner, 21 November 2026: "yung schedule table iparehas sa header ng revised file"):
    SLAB MARKED | SLAB THICKNESS | BOTTOM REINFORCEMENT (along short span / along long span: full length, curtailed) |
    TOP REINFORCEMENT (over long support / over short support: continuous support, end support) | DISTRIBUTION */
 static readonly string[] Level3={"FULL LENGTH","CURTAILED","FULL LENGTH","CURTAILED","CONTINUOUS SUPPORT","END SUPPORT","CONTINUOUS SUPPORT","END SUPPORT"};
 static readonly string[] Level2={"ALONG SHORT SPAN","ALONG LONG SPAN","OVER LONG SUPPORT","OVER SHORT SUPPORT"};
 void PaintHeader(object sender,DataGridViewCellPaintingEventArgs e){if(e.RowIndex!=-1||e.ColumnIndex<0)return;var g=e.Graphics;var cell=e.CellBounds;
  /* the same colours as the Beam Formatter header: one navy header, white group titles and captions */
  var font=e.CellStyle.Font;var navy=Color.FromArgb(20,33,51);/* owner (22 November 2026): the whole header is navy with white captions */using(var headBrush=new SolidBrush(navy))g.FillRectangle(headBrush,cell);using(var headPen=new Pen(Color.FromArgb(210,220,230)))g.DrawRectangle(headPen,cell.Left,cell.Top,cell.Width-1,cell.Height-1);var flags=TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak;
  Func<int,int,Rectangle,Rectangle> span=(first,last,band)=>{int left=cell.Left,width=0;for(int k=first;k<=last;k++){if(!grid.Columns[k].Visible)continue;if(k<e.ColumnIndex)left-=grid.Columns[k].Width;width+=grid.Columns[k].Width;}return new Rectangle(left,band.Top,width,band.Height);};
  int c=e.ColumnIndex;/* the bottom band takes two lines (CONTINUOUS / SUPPORT) at any display scale (owner, 22 November 2026: "naayos na ba ito") */int line=font.Height,bandH=line+10,need=2*bandH+2*line+10;if(grid.ColumnHeadersHeight<need){grid.ColumnHeadersHeight=need;return;}int third=bandH;var top=new Rectangle(cell.Left,cell.Top,cell.Width,third);var mid=new Rectangle(cell.Left,cell.Top+third,cell.Width,third);var bottom=new Rectangle(cell.Left,cell.Top+2*third,cell.Width,cell.Height-2*third);
  Action<Rectangle,string> navyBand=(r,t)=>{var state=g.Save();g.SetClip(new Rectangle(cell.Left,r.Top,cell.Width,r.Height));using(var b=new SolidBrush(navy))g.FillRectangle(b,r);using(var pen=new Pen(Color.FromArgb(210,220,230)))g.DrawRectangle(pen,r.Left,r.Top,r.Width-1,r.Height-1);TextRenderer.DrawText(g,t,font,r,Color.White,flags);g.Restore(state);};
  if(c>=2&&c<=9){navyBand(span(c<=5?2:6,c<=5?5:9,top),c<=5?"BOTTOM REINFORCEMENT":"TOP REINFORCEMENT");int pair=2+((c-2)/2)*2;navyBand(span(pair,pair+1,mid),Level2[(c-2)/2]);TextRenderer.DrawText(g,Level3[c-2],font,Rectangle.Inflate(bottom,-3,0),Color.White,flags);}
  else{string t=c==0?"SLAB MARK":c==1?"SLAB THICKNESS":c==10?"DISTRIBUTION":grid.Columns[c].HeaderText.ToUpperInvariant();TextRenderer.DrawText(g,t,font,Rectangle.Inflate(cell,-4,-2),Color.White,flags);}
  e.Handled=true;}
 void Guard(){if(!AccessCodes.CanUseApp(ProgramAccess.SlabFormatter))throw new Exception("Renew Schedule Formatter access.");}
 void InvalidateOutput(){result=null;export.Enabled=false;grid.Rows.Clear();if(cad.Image!=null){cad.Image.Dispose();cad.Image=null;}status.Text="Build preview to apply the current prefix, floor title and grouping.";}
 void Choose(){try{Guard();using(var dialog=new OpenFileDialog{Filter="Slab schedule DXF|*.dxf"})if(dialog.ShowDialog(this)==DialogResult.OK){string input=File.ReadAllText(dialog.FileName);SlabScheduleReader.Read(input);raw=input;source.Text="Loaded DXF: "+Path.GetFileName(dialog.FileName);InvalidateOutput();Build();}}catch(Exception x){MessageBox.Show(this,x.Message,"Slab source");}}
 internal void LoadSource(string input,string name){SlabScheduleReader.Read(input);raw=input;source.Text="Loaded DXF: "+name;Build();}
 void Build(){if(busy)return;busy=true;try{Guard();if(raw==null)throw new Exception("Load an original slab schedule DXF first.");InvalidateOutput();var built=SlabFormatter.Build(raw,prefix.Text,floor.Text,merge.Checked);bool aci=AciDetailing.IsAci(detailing);if(aci)AciDetailing.Apply(built.Drawing,"Slab");foreach(var group in built.Groups){var values=new object[12];values[0]=group.Mark;values[1]=group.Schedule.Thickness.ToString("0.00");for(int c=0;c<9;c++)values[c+2]=aci?AciDetailing.Notation(SlabFormatter.BarText(group.Schedule.Bars[c]),"Slab"):SlabFormatter.BarText(group.Schedule.Bars[c]).Replace("%%C","\u00d8");values[11]=group.Originals;grid.Rows.Add(values);}cad.Image=Preview.Render(built.Drawing);result=built;export.Enabled=true;status.Text=built.SourceCount+" original slab marks > "+built.Groups.Count+" output rows | "+prefix.Text+" | "+floor.Text;}catch(Exception x){MessageBox.Show(this,x.Message,"Slab preview");}finally{busy=false;}}
 void Export(){try{Guard();if(result==null)throw new Exception("Build preview first.");using(var dialog=new SaveFileDialog{Filter="Revised slab DXF|*.dxf",FileName=prefix.Text+" Slab Schedule - Revised.dxf"})if(dialog.ShowDialog(this)==DialogResult.OK){SlabFormatter.Export(result,dialog.FileName);status.Text="Exported: "+dialog.FileName;}}catch(Exception x){MessageBox.Show(this,x.Message,"Slab export");}}
}
